-- Seed launch configuration and the two versioned platform documents after migrations.
-- Re-running this file replaces the seed documents; do not run it over live data without a backup.

insert into storage.buckets (
  id,
  name,
  public,
  file_size_limit,
  allowed_mime_types
)
values (
  'media',
  'media',
  true,
  52428800,
  array['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'video/mp4', 'video/webm']
)
on conflict (id) do update set
  public = true,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

insert into public.platform_documents (key, payload, version) values
('site', $skie_site${"brand":{"name":"SKIE EVENTS","statement":"High-energy nights with house-party intimacy, club-scale production and a world that feels unmistakably Skie.","instagramUrl":"https://instagram.com/skieevents","contactEmail":"hello@skieevents.com","contactPhone":"","accent":"#5170FF"},"about":{"eyebrow":"About Skie","title":"A party company with a world of its own.","body":["Skie exists in the space between a house party and a major night out: intimate enough to feel personal, produced enough to feel impossible to ignore.","We care about the entire experience: the poster, the first message, the application, the line at the door, the room, the sound and the story people carry out with them.","This platform is the operating system behind every Skie night, built for events, applications, tickets, sponsors, media and community."]},"settings":{"appMode":"test","currency":"AUD","timezone":"Australia/Melbourne","defaultTicketLimit":2,"defaultAllocationExpiryHours":48,"newsletterEnabled":true,"featuredSponsorCarousel":false},"heroSlides":[{"id":"hero_001","active":true,"kicker":"SKIE EVENTS / MELBOURNE","title":"THE NIGHT STARTS BEFORE THE DOOR.","subtitle":"Applications, tickets, extras and every Skie signal in one place.","imageUrl":"","videoUrl":"","ctaLabel":"Explore events","ctaHref":"/events"},{"id":"hero_002","active":true,"kicker":"PRIVATE RELEASE","title":"NOT ANOTHER NIGHT OUT.","subtitle":"Invite-led rooms, close-range energy and a crowd selected for the atmosphere.","imageUrl":"","videoUrl":"","ctaLabel":"Inside Skie","ctaHref":"/about"}],"events":[{"id":"evt_redline_2026","slug":"redline-house-party","title":"Redline House Party","date":"2026-10-31","endDate":"2026-11-01","time":"8:30 PM – LATE","venue":"Private Residence","location":"Melbourne, VIC","genre":"HOUSE PARTY / OPEN FORMAT","teaser":"A private address pushed past its safe operating limit.","description":"Redline is a deliberately oversized house party with rooms that move differently,