],"ageRestriction":"18+","lifecycle":"archived","visibility":"archived","ticketMode":"closed","featured":false,"sponsorIds":["sp_nocturne"],"venueCapacity":180,"publicCapacity":150,"sponsorAllocation":10,"guestlistAllocation":10,"teamAllocation":5,"safetyBuffer":5,"defaultTicketLimit":2,"productIds":[],"ticketTypes":[{"id":"tt_zero","name":"General Admission","description":"Skie Zero admission.","priceCents":2000,"capacity":150,"sold":150,"defaultMaxPerCustomer":2,"active":false}]}],"products":[{"id":"prod_drinks_3","eventId":"evt_redline_2026","name":"3 Drink Pass","description":"Three eligible house drinks redeemed at the event bar. 18+ and valid ID required.","type":"drink_pass","priceCents":4500,"stockQuantity":100,"soldQuantity":0,"maxPerOrder":2,"maxPerCustomer":2,"requiresApproval":true,"requiresTicket":true,"isRedeemable":true,"imageUrl":"","active":true,"visibleOnEventPage":true,"unitsPerPurchase":3},{"id":"prod_queue_jump","eventId":"evt_redline_2026","name":"Priority Entry","description":"Dedicated priority entry lane before the published cut-off.","type":"add_on","priceCents":1500,"stockQuantity":40,"soldQuantity":0,"maxPerOrder":1,"maxPerCustomer":1,"requiresApproval":true,"requiresTicket":true,"isRedeemable":true,"imageUrl":"","active":true,"visibleOnEventPage":true,"unitsPerPurchase":1}],"sponsors":[{"id":"sp_nocturne","name":"NOCTURNE","tagline":"Night partner","description":"Independent nightlife support for rooms that put the crowd first.","logoUrl":"","bannerUrl":"","websiteUrl":"https://example.com","instagramUrl":"","active":true},{"id":"sp_sideb","name":"SIDE B","tagline":"Culture partner","description":"A culture platform built around the other side of the record.","logoUrl":"","bannerUrl":"","websiteUrl":"https://example.com","instagramUrl":"","active":true}],"media":[{"id":"media_1","title":"Hands above the room","eventName":"Skie Zero","eventId":"evt_skie_zero","type":"image","url":"","featured":true,"published":true},{"id":"media_2","title":"Before the drop","eventName":"Skie Zero","eventId":"evt_skie_zero","type":"image","url":"","featured":true,"published":true},{"id":"media_3","title":"2:14 AM","eventName":"Skie Zero","eventId":"evt_skie_zero","type":"image","url":"","featured":true,"published":true}],"reviews":[{"id":"review_1","name":"Maya","rating":5,"body":"It felt like everyone knew the same secret. The energy was close, loud and completely different from a standard club night.","status":"hidden","featured":true,"createdAt":"2026-03-15T03:20:00.000Z"},{"id":"review_2","name":"Arjun","rating":5,"body":"The room actually had personality. The music changed without killing the flow and the whole thing felt properly considered.","status":"hidden","featured":true,"createdAt":"2026-03-15T04:05:00.000Z"},{"id":"review_155804b062d76f2ae024af6e","userId":"local-admin","name":"abc","rating":5,"body":"greatgreatgreatgreatgreatgreatgreatgreat","status":"approved","featured":false,"createdAt":"2026-07-17T04:33:24.457Z"}],"forms":[{"id":"form_invite","name":"Invite-only application","intro":"Tell us enough to understand who is joining the room. Approval unlocks a limited ticket allocation in your account.","active":true,"fields":[{"id":"f_instagram","key":"instagram","label":"Instagram handle","type":"text","required":true,"placeholder":"@yourhandle","options":[],"maxLength":80},{"id":"f_occupation","key":"occupation","label":"Occupation or university","type":"text","required":false,"placeholder":"Optional","options":[],"maxLength":120},{"id":"f_invited","key":"invited_by","label":"Who invited you?","type":"text","required":false,"placeholder":"Name or account","options":[],"maxLength":120},{"id":"f_hear","key":"heard_from","label":"How did you hear about this event?","type":"select","required":true,"placeholder":"Choose one","options":["Instagram","Friend","Previous Skie event","Sponsor or artist","Other"]},{"id":"f_reason","key":"why_join","label":"Why do you want to join this release?","type":"textarea","required":true,"placeholder":"Keep it real.","options":[],"maxLength":600},{"id":"f_age","key":"age_confirmed","label":"Age confirmation","type":"checkbox","required":true,"placeholder":"I confirm I am 18+ and can provide valid photo ID at entry.","options":[]},{}]}],"emailTemplates":[{"id":"email_application_received","key":"application_received","name":"Application received","subject":"We received your {{event_title}} application","html":"<h1>Application received.</h1><p>Hi {{first_name}}, your application for <strong>{{event_title}}</strong> is now under review.</p>","active":true,"updatedAt":"2026-07-17T00:00:00.000Z"},{"id":"email_ticket_unlocked","key":"ticket_unlocked","name":"Ticket unlocked","subject":"Your {{event_title}} ticket is unlocked","html":"<h1>Your ticket is unlocked.</h1><p>Hi {{first_name}}, log in to buy up to {{max_quantity}} ticket(s) before {{expires_at}}.</p><p><a href=\"{{account_url}}\">Open your account</a></p>","active":true,"updatedAt":"2026-07-17T00:00:00.000Z"},{"id":"email_ticket_issued","key":"ticket_issued","name":"Ticket issued","subject":"Your {{event_title}} ticket is ready","html":"<h1>You are in.</h1><p>Your ticket for <strong>{{event_title}}</strong> is available in your account.</p><p><a href=\"{{ticket_url}}\">Open ticket</a></p>","active":true,"updatedAt":"2026-07-17T00:00:00.000Z"},{"id":"email_waitlist","key":"waitlist","name":"Waitlist","subject":"Update on your {{event_title}} application","html":"<h1>You are on the waitlist.</h1><p>We will contact you if an allocation becomes available.</p>","active":true,"updatedAt":"2026-07-17T00:00:00.000Z"},{"id":"email_not_selected","key":"not_selected","name":"Not selected","subject":"Update on your {{event_title}} application","html":"<h1>Not selected for this release.</h1><p>Thank you for applying. This decision only applies to this release.</p>","active":true,"updatedAt":"2026-07-17T00:00:00.000Z"},{"id":"email_payment_reminder","key":"payment_reminder","name":"Payment reminder","subject":"Your {{event_title}} ticket is still unlocked","html":"<h1>Your ticket is waiting, {{first_name}}.</h1><p>Your access to {{event_title}} is unlocked until {{expires_at}}.</p><p><a href=\"{{account_url}}\">Open your Skie account</a></p>","active":true,"updatedAt":"2026-07-17T00:00:00.000Z"}],"legalPages":[{"id":"legal_terms","slug":"terms","title":"Terms & Conditions","version":"1.0","publishedAt":"2026-07-17T00:00:00.000Z","content":"These terms govern applications, ticket purchases, event access and use of the Skie Events platform. Tickets remain subject to event-specific conditions, capacity and venue rules."},{"id":"legal_privacy","slug":"privacy","title":"Privacy Policy","version":"1.0","publishedAt":"2026-07-17T00:00:00.000Z","content":"Skie Events collects information needed to manage applications, payments, tickets, event safety and communications. Sponsor data is only exported where the relevant consent was recorded."},{"id":"legal_refund","slug":"refund-policy","title":"Refund Policy","version":"1.0","publishedAt":"2026-07-17T00:00:00.000Z","content":"Refund eligibility depends on the event, product and reason. Event cancellation and major changes will be handled according to Australian consumer law and the published event terms."},{"id":"legal_entry","slug":"entry-policy","title":"Entry Policy","version":"1.0","publishedAt":"2026-07-17T00:00:00.000Z","content":"All events are 18+ unless expressly stated otherwise. Valid photo ID is required. Management and venue security reserve the right to refuse entry for safety, intoxication, aggression or breach of event rules."},{"id":"legal_media","slug":"media-release","title":"Media Release","version":"1.0","publishedAt":"2026-07-17T00:00:00.000Z","content":"Photography and video may be captured at Skie Events and used in event recaps and brand marketing. Contact us if you have a specific safety or privacy concern."},{"id":"legal_age","slug":"age-policy","title":"Age Policy","version":"1.0","publishedAt":"2026-07-17T00:00:00.000Z","content":"Skie nightlife events are 18+ and require valid government-issued photo identification at entry."}]}$skie_site$::jsonb, 1),
('operations', $skie_ops${"users":[],"consents":[],"applications":[],"allocations":[],"orders":[],"payments":[],"tickets":[],"entitlements":[],"checkIns":[],"emailLogs":[],"auditLogs":[],"contacts":[],"newsletter":[]}$skie_ops$::jsonb, 1)
on conflict (key) do update
set payload = excluded.payload,
    version = public.platform_documents.version + 1,
    updated_at = now();

-- Replace the legacy empty form-field placeholder with explicit optional consent fields.
update public.platform_documents
set payload = jsonb_set(
      payload,
      '{forms,0,fields}',
      (
        case
          when payload #> '{forms,0,fields,-1}' = '{}'::jsonb
            then (payload #> '{forms,0,fields}') - (jsonb_array_length(payload #> '{forms,0,fields}') - 1)
          else payload #> '{forms,0,fields}'
        end
      ) || jsonb_build_array(
        jsonb_build_object(
          'id', 'f_media',
          'key', 'media_consent',
          'label', 'Media consent',
          'type', 'checkbox',
          'required', false,
          'placeholder', 'I consent to photos and video of me being used in Skie Events recaps and marketing.',
          'options', jsonb_build_array()
        ),
        jsonb_build_object(
          'id', 'f_sponsor',
          'key', 'sponsor_consent',
          'label', 'Sponsor consent',
          'type', 'checkbox',
          'required', false,
          'placeholder', 'I consent to my contact details being shared with named sponsors of this event.',
          'options', jsonb_build_array()
        )
      )
    ),
    version = version + 1,
    updated_at = now()
where key = 'site';
